type RuneWasmModule = {
  default: () => Promise<unknown>;
};

function hideSplash(): void {
  const splash = document.getElementById('splash');
  splash?.classList.add('hide');
  window.setTimeout(() => splash?.remove(), 350);
}

/**
 * Load Rune's wasm-bindgen output generated by "pnpm --filter datazen-web build:rune-ui".
 * It is deliberately runtime-only so the standard React build does not require WASM assets.
 */
export async function startRuneUi(): Promise<void> {
  try {
    const entrypoint = new URL('rune-ui/app.js', document.baseURI);
    const module = (await import(/* @vite-ignore */ entrypoint.href)) as RuneWasmModule;
    await module.default();
    hideSplash();
  } catch (error) {
    console.error('[rune-ui] failed to start the Rune UI', error);
    hideSplash();

    const root = document.querySelector<HTMLDivElement>('#root');
    if (!root) return;

    const panel = document.createElement('main');
    panel.className =
      'flex h-full min-h-0 flex-col items-center justify-center gap-3 p-8 text-center';

    const title = document.createElement('h1');
    title.className = 'text-xl font-semibold';
    title.textContent = 'Rune UI could not start';

    const detail = document.createElement('p');
    detail.className = 'max-w-xl text-sm text-muted-foreground';
    detail.textContent = error instanceof Error ? error.message : String(error);

    const fallback = document.createElement('a');
    fallback.className = 'text-sm underline underline-offset-4';
    const standardUrl = new URL(window.location.href);
    standardUrl.searchParams.delete('ui');
    fallback.href = standardUrl.toString();
    fallback.textContent = 'Open the standard DataZen Web UI';

    panel.append(title, detail, fallback);
    root.replaceChildren(panel);
  }
}
